#include <pybind11/pybind11.h>
#include <torch/extension.h>
#include "acl/acl.h"
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "ap_tiling.h"
extern "C" void ap_do_fp32(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*);
namespace ap_ext {
using LF=void(*)(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*);
pybind11::tuple run_avg_pool2d(const at::Tensor &x, int64_t kH, int64_t kW, int64_t stride, int64_t pad) {
    TORCH_CHECK(kH==2&&kW==2&&stride==2&&pad==0,"only k=2,s=2,p=0 supported");
    TORCH_CHECK(x.dim()==4&&x.scalar_type()==at::kFloat,"[N,C,H,W] fp32 only");
    TORCH_CHECK(x.is_contiguous(),"must be contiguous");
    const auto N=x.sizes()[0], C=x.sizes()[1], H=x.sizes()[2], W=x.sizes()[3];
    const auto Ho=H/2, Wo=W/2;
    const auto M=static_cast<int32_t>(N*C*Ho);
    const auto mNum=(M+DEFAULT_BLOCK_M-1)/DEFAULT_BLOCK_M;
    const auto uc=std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,mNum);
    const auto tpc=(mNum+uc-1)/uc;
    at::Tensor y=at::empty({N,C,Ho,Wo},x.options());
    at::Tensor tc=at::empty({static_cast<long>(sizeof(APKernelTiling))},at::device(at::kCPU).dtype(at::kByte));
    auto *t=reinterpret_cast<APKernelTiling*>(tc.data_ptr());
    t->M=M; t->N=static_cast<int32_t>(Wo); t->blockM=DEFAULT_BLOCK_M; t->usedCoreNum=uc; t->tasksPerCore=tpc;
    t->W=static_cast<int32_t>(W); t->Ho=static_cast<int32_t>(Ho);
    t->inChStride=static_cast<int32_t>(H*W); t->outChStride=static_cast<int32_t>(Ho*Wo);
    t->inTotal=static_cast<int32_t>(N*C*H*W);
    auto tn=tc.to(at::kPrivateUse1);
    auto stm=c10_npu::getCurrentNPUStream().stream(false);
    ap_do_fp32(uc,stm,
        static_cast<uint8_t*>(const_cast<void*>(x.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(y.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(tn.storage().data())));
    return pybind11::make_tuple(y);
}}
PYBIND11_MODULE(_avg_pool2d_ext, m) { m.def("run_avg_pool2d",&ap_ext::run_avg_pool2d,""); }

