#pragma once
#ifndef AP_TILING_H
#define AP_TILING_H
#include <cstdint>
constexpr int32_t DEFAULT_BLOCK_M = 128;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 32;
struct APKernelTiling { int32_t M; int32_t N; int32_t blockM; int32_t usedCoreNum; int32_t tasksPerCore;
    int32_t W; int32_t Ho; int32_t inChStride; int32_t outChStride; int32_t inTotal; };
#endif

